function SubscriberAutocomplete({endpoint,field,value,onChange,icon:Icon,placeholder,required=true,compact=false,invalid=false}:{endpoint:string;field:SuggestField;value:string;onChange:(value:string)=>void;icon:any;placeholder:string;required?:boolean;compact?:boolean;invalid?:boolean}){
 const [suggestions,setSuggestions]=useState<string[]>([]),[open,setOpen]=useState(false),[active,setActive]=useState(0),[dismissedValue,setDismissedValue]=useState("");
 useEffect(()=>{const query=value.trim();if(query.length<2||query===dismissedValue){setSuggestions([]);setOpen(false);return;}let live=true;const timer=window.setTimeout(async()=>{try{const response=await fetch(`${endpoint}/subscribers/suggestions?field=${field}&q=${encodeURIComponent(query)}`,{credentials:"include",cache:"no-store"});if(!response.ok)throw new Error();const data=await response.json();if(live){setSuggestions(Array.isArray(data.items)?data.items.filter((item:any)=>typeof item==="string"):[]);setActive(0);setOpen(true);}}catch{if(live){setSuggestions([]);setOpen(false);}}},180);return()=>{live=false;window.clearTimeout(timer);};},[endpoint,field,value,dismissedValue]);
 const choose=(value:string)=>{setDismissedValue(value);onChange(value);setOpen(false);};
 const update=(value:string)=>{setDismissedValue("");onChange(value);};
 return <div className="relative min-w-0"><div className="relative"><Icon aria-hidden="true" className="pointer-events-none absolute right-3 top-1/2 z-[1] h-4 w-4 -translate-y-1/2 text-sky-600"/><ProjectInput required={required} aria-invalid={invalid||undefined} className={`${inputClass} pr-10 ${compact?"!text-[14px] placeholder:!text-[10px]":""} ${invalid?"!border-rose-500 focus:!border-rose-500 focus:!ring-rose-100 dark:!border-rose-400":""}`} value={value} onChange={event=>update(event.target.value)} onFocus={()=>{if(suggestions.length)setOpen(true);}} onBlur={()=>window.setTimeout(()=>setOpen(false),120)} onKeyDown={event=>{if(!open||!suggestions.length)return;if(event.key==="ArrowDown"){event.preventDefault();setActive(index=>(index+1)%suggestions.length);}else if(event.key==="ArrowUp"){event.preventDefault();setActive(index=>(index-1+suggestions.length)%suggestions.length);}else if(event.key==="Tab"){choose(suggestions[active]||suggestions[0]);}else if(event.key==="Escape"){setOpen(false);}}} maxLength={field==="address"?10000:100} placeholder={placeholder} autoComplete="off" aria-autocomplete="list" aria-expanded={open&&suggestions.length>0}/></div>{open&&suggestions.length>0&&<div role="listbox" className="absolute inset-x-0 top-[calc(100%+6px)] z-50 max-h-52 overflow-y-auto rounded-xl border border-[#b8cde2] bg-white p-1.5 shadow-[0_14px_34px_rgba(31,56,86,.18)] dark:border-white/15 dark:bg-[#1b2b3f]">{suggestions.map((item,index)=><button key={item} type="button" role="option" aria-selected={active===index} tabIndex={-1} onMouseEnter={()=>setActive(index)} onMouseDown={event=>event.preventDefault()} onClick={()=>choose(item)} className={`flex min-h-9 w-full items-center gap-2 rounded-lg px-2.5 text-right text-xs transition ${active===index?"bg-blue-50 text-[#0758e9] dark:bg-blue-500/10 dark:text-blue-200":"text-slate-700 hover:bg-slate-50 dark:text-slate-200 dark:hover:bg-white/5"}`}><Icon className="h-4 w-4 shrink-0 text-sky-600"/><span className="truncate">{item}</span></button>)}</div>}</div>;
}


