 <ProjectDialog open={Boolean(pppoeUsageHistory)} title="سجل استهلاك PPPoE" description={pppoeUsageHistory?`آخر جلسات RADIUS للمستخدم ${pppoeUsageHistory.line.username}`:""} onClose={()=>{if(!pppoeUsageHistoryLoading)setPppoeUsageHistory(null);}} busy={pppoeUsageHistoryLoading} maxWidth="max-w-3xl" footer={<ProjectButton variant="secondary" disabled={pppoeUsageHistoryLoading} onClick={()=>setPppoeUsageHistory(null)}><X/>إغلاق</ProjectButton>}>{pppoeUsageHistoryError?<p role="alert" className="rounded-xl border border-rose-200 bg-rose-50 p-3 text-xs text-rose-700 dark:border-rose-300/15 dark:bg-rose-500/[.06] dark:text-rose-200">{pppoeUsageHistoryError}</p>:pppoeUsageHistoryLoading?<CollectionState>جارٍ تحميل سجل الاستهلاك…</CollectionState>:pppoeUsageHistory?.sessions.length?<div className="max-h-[65vh] space-y-2 overflow-y-auto">{pppoeUsageHistory.sessions.map((session:any,index:number)=><article key={`${session.started_at||"session"}-${index}`} className="grid gap-2 rounded-xl border border-slate-200 bg-white p-3 text-[11px] dark:border-white/10 dark:bg-white/[.025] sm:grid-cols-2 lg:grid-cols-4"><div className="flex items-center gap-2 text-slate-600 dark:text-slate-300"><Clock3 className="h-4 w-4 shrink-0 text-blue-600"/><span>بدأت: {detailDate(session.started_at)}</span></div><div>انتهت: <strong>{session.stopped_at?detailDate(session.stopped_at):"جلسة قائمة"}</strong></div><div>رفع: <strong>{bytesLabel(session.upload_bytes)}</strong></div><div>تنزيل: <strong>{bytesLabel(session.download_bytes)}</strong></div><div>المدة: <strong>{Number(session.session_seconds||0).toLocaleString("ar")} ثانية</strong></div><div>NAS: <bdi dir="ltr">{session.nas_ip||"—"}</bdi></div><div>IP: <bdi dir="ltr">{session.framed_ip||"—"}</bdi></div><div>MAC: <bdi dir="ltr">{session.calling_station_id||"—"}</bdi></div></article>)}</div>:<CollectionState>لا توجد جلسات محفوظة لهذا الخط في RADIUS.</CollectionState>}</ProjectDialog>
